function getActorNode()
						local node = window.getDatabaseNode();

						while node do
							if DB.getValue(node, "name", "") ~= "" then
								return node;
							end

							node = node.getParent();
						end

						return nil;
					end

					function getActorNameFromNode(nodeActor)
						if not nodeActor then
							return "Unknown Actor";
						end

						local rActor = ActorManager.resolveActor(nodeActor);

						if rActor then
							return ActorManager.getDisplayName(rActor);
						end

						return DB.getValue(nodeActor, "name", "Unknown Actor");
					end

					function onButtonPress()
						local nUnchecked = 0;

						local function isCheckboxName(sName)
							if not sName then
								return false;
							end

							local s = sName:lower();

							return s:match("checkbox");
					--			or s:match("_chk")
					--			or s:match("scratch_item")
					--			or s:match("scratch_item_chk");
						end

						local function resetCheckboxNodes(node)
							if not node then
								return;
							end

							for _, nodeChild in pairs(DB.getChildren(node)) do
								local sChildName = nodeChild.getName() or "";

								if isCheckboxName(sChildName) then
									local v = DB.getValue(nodeChild, "", 0);

									if tonumber(v) ~= 0 then
										nUnchecked = nUnchecked + 1;
									end

									DB.setValue(nodeChild, "", "number", 0);
								end

								resetCheckboxNodes(nodeChild);
							end
						end

						local tSeen = {};

						local function resetCheckboxControls(w)
							if not w then
								return;
							end

							if tSeen[w] then
								return;
							end

							tSeen[w] = true;

							if not w.getControls then
								return;
							end

							for _, c in pairs(w.getControls()) do
								local sName = "";

								if c.getName then
									sName = c.getName() or "";
								end

								if isCheckboxName(sName) then
									if c.setValue then
										if c.getValue and tonumber(c.getValue()) ~= 0 then
											nUnchecked = nUnchecked + 1;
										end

										c.setValue(0);
									end
								end

								if c.getWindows then
									for _, wChild in ipairs(c.getWindows()) do
										resetCheckboxControls(wChild);
									end
								end

								if c.getSubwindow then
									local wSub = c.getSubwindow();

									if wSub then
										resetCheckboxControls(wSub);
									end
								end
							end
						end

						local nodeWin = window.getDatabaseNode();

						if nodeWin then
							resetCheckboxNodes(nodeWin);
						end

						resetCheckboxControls(window);

						ModifierStack.reset();

						local nodeActor = getActorNode();
						local sActorName = getActorNameFromNode(nodeActor);

						manager_resetstatus.sendResetTagsStatusesMessage(sActorName);

						-- Debug.chat("Unchecked checkboxes:", nUnchecked);
					end

