function onButtonPress()
						local bCurrentlyVisible = getFirstListButtonVisibleState(window);

						if bCurrentlyVisible == nil then
							return;
						end

						setListButtonsVisible(window, not bCurrentlyVisible);
					end

					function isTargetListButton(ctrl)
						if not ctrl then
							return false;
						end

						local sName = ctrl.getName();

						if not sName then
							return false;
						end

						return string.find(sName, "list_iadd") or string.find(sName, "list_iedit");
					end

					function getFirstListButtonVisibleState(w)
						if not w then
							return nil;
						end

						for _, ctrl in pairs(w.getControls()) do
							if isTargetListButton(ctrl) then
								return ctrl.isVisible();
							end

							if ctrl.getWindows then
								for _, row in pairs(ctrl.getWindows()) do
									local bFound = getFirstListButtonVisibleState(row);
									if bFound ~= nil then
										return bFound;
									end
								end
							end

							if ctrl.getSubWindow then
								local sub = ctrl.getSubWindow();
								if sub then
									local bFound = getFirstListButtonVisibleState(sub);
									if bFound ~= nil then
										return bFound;
									end
								end
							end
						end

						return nil;
					end

					function setListButtonsVisible(w, bVisible)
						if not w then
							return;
						end

						for _, ctrl in pairs(w.getControls()) do
							if isTargetListButton(ctrl) then
								ctrl.setVisible(bVisible);
							end

							if ctrl.getWindows then
								for _, row in pairs(ctrl.getWindows()) do
									setListButtonsVisible(row, bVisible);
								end
							end

							if ctrl.getSubWindow then
								local sub = ctrl.getSubWindow();
								if sub then
									setListButtonsVisible(sub, bVisible);
								end
							end
						end
					end

number.script:
function getActorName()
						local sActorName = "Actor";

						local nodeWin = window.getDatabaseNode();
						if nodeWin then
							local rActor = ActorManager.resolveActor(nodeWin);
							if rActor and rActor.sName and rActor.sName ~= "" then
								sActorName = rActor.sName;
							else
								sActorName = DB.getValue(nodeWin, "name", "Actor");
							end
						end

						return sActorName;
					end

					function onClickDown(x, y)
						local nMod = tonumber(getValue()) or 0;

						if nMod == 0 then
							return true;
						end

						ModifierStack.addSlot("Mod", nMod);

						local sActorName = getActorName();

						manager_modbutton.sendModButtonMessage(sActorName, nMod);

						return true;
					end

